enum class Status {
  idle,
  busy,
  online,
  offline_saved,
  unsaved,
  storage_blocked,
  key_rejected,
  creation_unconfirmed,
  failed,
};

// Value snapshot exposed as const by the controller; never carries credentials.
struct View {
  Status status = Status::idle;
  bool has_unsaved_key = false;
  std::optional<study_meta::PublicProfile> profile;
};

inline View present(const study_meta::BootstrapResult& result, bool unsaved) {
  View view;
  if (unsaved) {
    view.status = Status::unsaved;
    view.has_unsaved_key = true;
    view.profile.reset();
    return view;
  }

  switch (result.state) {
    case study_meta::BootstrapState::online:
      // Online requires a confirmed public profile.
      if (!result.profile.has_value()) {
        view.status = Status::failed;
        return view;
      }
      view.status = Status::online;
      view.profile = result.profile;
      return view;
    case study_meta::BootstrapState::offline_saved:
      view.status = Status::offline_saved;
      return view;
    case study_meta::BootstrapState::unsaved:
      view.status = Status::unsaved;
      view.has_unsaved_key = true;
      return view;
    case study_meta::BootstrapState::storage_blocked:
      view.status = Status::storage_blocked;
      return view;
    case study_meta::BootstrapState::key_rejected:
      view.status = Status::key_rejected;
      return view;
    case study_meta::BootstrapState::creation_unconfirmed:
      view.status = Status::creation_unconfirmed;
      return view;
    default:
      view.status = Status::failed;
      return view;
  }
}

inline bool may_connect(const View& view) {
  return view.status != Status::busy &&
         view.status != Status::creation_unconfirmed;
}

struct AccountOutcome {
    std::optional<BootstrapResult> result;
    bool has_unsaved_key = false;
};
// Confined to one job at a time. Session identity and any unsaved key survive jobs.
class AccountTask final {
public:
    AccountTask(int port, std::filesystem::path folder)
        : api_(port), folder_(std::move(folder)) {}
    AccountOutcome operator()() {
        try {
            // Acquire on the worker, then retain the lock between calls as well.
            if (!store_ || !store_->available())
                store_ = std::make_unique<LocalAccountStore>(folder_, api_.origin());
            const auto result = session_.connect(*store_, api_);
            return {result, session_.has_unsaved_key()};
        } catch (const std::exception&) {
            return {{}, session_.has_unsaved_key()};
        }
    }
private:
    AccountHttp api_;
    std::filesystem::path folder_;
    AccountBootstrap session_;
    std::unique_ptr<LocalAccountStore> store_;
};

explicit Controller(std::unique_ptr<Worker> worker) : worker_(std::move(worker)) {
    if (!worker_) throw std::invalid_argument("account worker required");
}
Controller(const Controller&) = delete;
Controller& operator=(const Controller&) = delete;
const View& view() const { return view_; }
bool busy() const { return job_.valid(); }
bool request() {
    if (busy() || !may_connect(view_)) return false;
    try {
        auto* worker = worker_.get();
        job_ = std::async(std::launch::async, [worker] { return (*worker)(); });
        view_.status = Status::busy;
        view_.profile.reset();
        return true;
    } catch (const std::exception&) {
        view_.status = view_.has_unsaved_key ? Status::unsaved : Status::failed;
        view_.profile.reset();
        return false;
    }
}

bool poll() {
    if (!busy() || job_.wait_for(std::chrono::seconds(0)) != std::future_status::ready)
        return false;
    try {
        const auto outcome = job_.get(); // consumes exactly once; publishes worker writes
        view_ = outcome.result ? present(*outcome.result, outcome.has_unsaved_key)
                               : View{outcome.has_unsaved_key ? Status::unsaved : Status::failed,
                                      outcome.has_unsaved_key, {}};
    } catch (const std::exception&) {
        view_.status = view_.has_unsaved_key ? Status::unsaved : Status::failed;
        view_.profile.reset();
    }
    return true;
}

private:
    std::unique_ptr<Worker> worker_;
    View view_;
    // Destroyed FIRST: async future joins before worker_ and its secret session die.
    // Destruction can block; the frame's poll uses only a zero-duration wait.
    std::future<study_meta::AccountOutcome> job_;

enum class Action { none, connect, back };
inline constexpr study_ui::Rect connect_bounds{110,132,180,28};
inline constexpr study_ui::Rect back_bounds{110,176,180,28};
inline Action evaluate(const View& view, const study_ui::Input& input,
                       bool confirm, bool back, bool cancelled) {
    if (cancelled) return Action::none;
    if (back) return Action::back;
    if (!input.cancelled && input.press) {
        if (study_ui::contains(back_bounds,*input.press)) return Action::back;
        if (study_ui::contains(connect_bounds,*input.press))
            return may_connect(view) ? Action::connect : Action::none;
        return Action::none; // A pointer press consumes this frame's confirm edge.
    }
    return confirm && may_connect(view) ? Action::connect : Action::none;
}

